  if(control.hasAttribute('data-tool-ability'))return 'Choose the ability the DM calls for on this tool check. The sheet adds your proficiency bonus, doubled once by Artificer Tool Expertise from class level 6. Save to retain the selected ability.';
  if(control.hasAttribute('data-weapon-training'))return D.boxes['weapon training & mastery'];
