  if(control.hasAttribute('data-metamagic')||control.hasAttribute('data-metamagic-level'))return D.boxes.metamagic;
  if(control.hasAttribute('data-bard-slot'))return D.boxes['font of inspiration'];
  if(control.hasAttribute('data-invocation-cantrip'))return 'Chooses the known Warlock cantrip enhanced by this invocation. Repeated copies must choose different cantrips. Damage and range are calculated from current Charisma and Warlock levels; save to keep the choice.';
  if(['eldritch-invocations','divine-order','primal-order','elemental-fury','blessed-strikes','metamagic'].includes(control.dataset.choiceGroup))return D.boxes[control.dataset.choiceGroup.replaceAll('-',' ')];
  if(control.matches('#sheetAdventureLog [data-log-part="start"],#sheetAdventureLog [data-log-part="gain"]')||control.closest('#sheetItemResources,#sheetItemResourceRecovery,#sheetClassSkillEditorGroup,#sheetSpeciesEditorGroup,#sheetCharacterLanguageChoices')||control.closest('[data-cleric-vitality]')||control.closest('[data-druid-slot-create]')||control.closest('[data-druid-resurgence]')||control.closest('#sheetDruidWildCompanion')||control.closest('#sheetDruidWildShape')||control.hasAttribute('data-paladin-aura'))return 'Applies your own Aura of Protection when available. The current Charisma bonus, minimum +1, is included once in saves. Recognised canonical conditions disable it according to your edition. Turn it off for other table restrictions or when replacing it with another Paladin’s aura; never add the same aura again as a manual save bonus. Save to retain this choice.';
  if(control.hasAttribute('data-channel-effect'))return 'Choose an unlocked Channel Divinity effect, then use its button to spend one use. Legacy Cleric and Paladin effects share one pool; revised classes track separate pools. Source-specific rolls, DCs and conditions are shown below. Save retains the last effect and use.';
  if(control.hasAttribute('data-arcane-slot'))return 'Choose the number of expended slots to recover after a Short Rest. All selected slots share one budget and one activation. Recover selected slots updates both slot spending and Arcane Recovery; save the sheet to retain both changes.';
  if(control.hasAttribute('data-class-resource-amount'))return 'Choose a whole-number amount within the pool limit. Spend points requires enough remaining points; Undo points requires that many previously spent points. Apply healing or condition removal to the recipient separately, then save the sheet to retain spending.';
  if(control.hasAttribute('data-class-feature-choice'))return 'Selects a class feature choice for this class and level, such as a Fighting Style or invocation. Class Fighting Styles and styles on Feats use the same allowance. Choose each style once; remove a saved style on Feats there before replacing it in class choices. The builder checks supported effects; save the sheet to retain it.';
  if(control.hasAttribute('data-subclass'))return 'Selects this class’s subclass when its class level allows it. It supplies unlocked subclass features and supported always-prepared spells.';
  if(control.hasAttribute('data-dm-member-role'))return D.labels['campaign role'];
  if(control.classList.contains('role-checkbox'))return {admin:'Grants global admin tools for accounts, DM applications and root catalogue content. Campaign access still requires membership.',dm:'Grants global DM access so this account can create campaigns. A campaign’s membership role determines management rights inside that campaign.',player:'Grants a standard player account. Campaign invitations and membership determine which campaigns and characters it can access.',viewer:'Keeps the account at viewer access. Campaign membership still determines access inside a campaign.'}[control.value];
  if(control.hasAttribute('data-dm-advancement'))return {bonusFeats:'Grants additional feat choices to this character beyond ordinary progression. The player chooses the feats on the Feats page.',bonusAsis:'Grants extra Ability Score Improvement choices for this character. This is a campaign-DM allowance, separate from normal class progression.',usedAsis:'Reserves how many of the extra choices have been used for ASIs instead of feats. It does not enter an ability score increase directly.',asiSpent:'Reserves normal advancement choices used for ASIs instead of feats. It reduces the normal feat allowance without changing base scores directly.'}[control.dataset.dmAdvancement];
  if(control.hasAttribute('data-feat-armor'))return 'Grants the custom feat’s explicit '+(control.dataset.featArmor==='shield'?'shield':control.dataset.featArmor+' armor')+' training. Supported training appears in Proficiencies & languages; description text alone does not grant it.';
  if(control.hasAttribute('data-feat-character'))return 'Chooses the campaign character that receives this custom feat. Assign feat also adds its protected bonus allowance; it does not assign the feat to every character.';
  if(control.hasAttribute('data-campaign-feat'))return 'Selects a campaign feat to edit its name, description or availability. Campaign changes do not rewrite the bundled catalogue, and existing character selections are retained.';
  if(control.hasAttribute('data-companion-skill'))return 'Chooses this creature’s skill proficiency or expertise. Wild Shape also uses supported character training when that is higher.';
  if(control.hasAttribute('data-companion-ability'))return 'Sets this creature’s ability score for its checks, attacks and saving throws. Wild Shape uses your character’s mental scores where its rules require them.';
  if(control.hasAttribute('data-companion-save'))return 'Marks this creature’s proficiency in the saving throw. Its ability modifier and proficiency bonus determine the displayed save.';
  const comp=control.dataset.companionField;
  if(comp){const texts={type:'Choose companion, familiar or a manual Wild Shape reference. The manual reference retains supported mental-score and skill values; use the separate Wild Shape controls to manage the actual Druid form, uses and HP.',name:'Names this creature without changing its creature rules.',ac:'Sets this creature’s Armor Class, the defense used against attack rolls.',hpMax:'Sets this creature’s maximum HP. It is separate from your character’s HP.',hpCurrent:'Tracks this companion’s current HP without changing your character’s HP.',hpTemp:'Tracks temporary HP on this companion, separate from current and maximum HP.',deathSuccess:'Records up to three death save successes for this companion. It does not change your character’s death saves.',deathFailure:'Records up to three death save failures for this companion. It does not change your character’s death saves.',hitDiceUsed:'Records how many of this creature’s catalogue hit dice have been spent. Resolve healing and rest recovery through your table’s rules before adjusting the counter.',features:'Records additional features for this companion. These notes do not automatically grant actions or numeric bonuses.',creatureType:'Describes the creature type, such as Beast or Celestial. Choosing another catalogue creature restores its catalogue type.',speed:'Sets this creature’s movement speed in feet.',profBonus:D.labels['proficiency bonus'],initiativeBonus:'Adds an initiative adjustment to this creature’s Dexterity modifier.',attacks:'Records this creature’s attacks and combat reminders.',traits:D.labels.traits,notes:D.fields.notes||D.labels.notes,size:D.labels.size};return texts[comp]||'Records '+comp+' for this creature.';}
  if(/language/.test(name)||/language/i.test(key))return 'Chooses a language granted by this character choice. The selected language appears with Proficiencies & languages on Overview.';
  if(/tool/.test(name)||/tool/i.test(key))return 'Chooses tool training granted by this option. Supported training appears in the character’s proficiencies.';
  if(/skill/.test(name)||/skill/i.test(key))return 'Chooses a skill granted by this character option. Supported proficiency is included in the final skill modifier.';
  if(/ability.*(increase|choose)|asi|background.*(bonus|ability)/.test(name)||/^build\.(asi|backgroundAsi)/.test(key))return 'Chooses an ability increase granted by this option. Eligible choices and limits follow its rules; supported increases are added to base scores and shown in the ability breakdown.';
  if(/feat/.test(name)&&control.tagName==='SELECT')return 'Selects the feat for this granted choice. Review its prerequisites and complete any ability or training choices on the Feats page.';
  if(/attunement|required.*attune/.test(name))return 'Marks whether the item requires attunement. Players manage actual attunement in Active Gear; its supported magical effects depend on this requirement.';
